	// Small memo of struct plan lookups: the key-values of a table hit the
	// same few struct types over and over, and the global cache lookup costs
	// an interface hash every time. Hits swap the entry one slot toward the
	// front (transpose heuristic); misses overwrite a rotating slot, so a
	// document with more hot types than slots degrades to a handful of
	// pointer comparisons instead of shifting the whole array per lookup.
	planMemo [8]struct {
		t reflect.Type
		p *structPlan
	}
	planClock uint8
}

// planFor returns the struct plan of t, memoizing recent lookups.
func (d *decoder) planFor(t reflect.Type) *structPlan {
	if d.planMemo[0].t == t {
		return d.planMemo[0].p
	}
	for i := 1; i < len(d.planMemo); i++ {
		if d.planMemo[i].t == t {
			d.planMemo[i-1], d.planMemo[i] = d.planMemo[i], d.planMemo[i-1]
			return d.planMemo[i-1].p
		}
	}
	p := planForType(t)
	i := int(d.planClock) % len(d.planMemo)
	d.planClock++
	d.planMemo[i].t, d.planMemo[i].p = t, p
	return p

<<END_SOURCE>>
<<SOURCE {"id":"theirs"}>>

	// Scratch buffers of the fused generic decode path for container values:
	// anyStack accumulates array elements (and kvStack inline-table pairs)
	// before the exact-size copy-out; fusedParts and fusedOps record the keys
	// seen inside a container value so they can be validated by the
	// seen-tracker after the whole expression has parsed (preserving error
	// precedence); idStack is the scope stack used during that replay.
	anyStack   []interface{}
	kvStack    []fusedKV
	fusedParts [][]byte
	fusedOps   []fusedOp
	idStack    []int32

	// fusedNesting is the current depth of nested containers being decoded
	// natively, bounded by maxFusedNesting (see fusedContainerValue).
	fusedNesting int

	// Fused struct-path state: keyRaws is the reusable buffer of raw key-part
	// spans matching keyParts; fusedKVParts/fusedKVKeyRange describe the key
	// of the key-value being decoded (for strict-mode reporting) and
	// fusedValueSpan the exact raw span of its value (for error highlights).
	keyRaws         [][]byte
	fusedKVParts    [][]byte
	fusedKVKeyRange unstable.Range
	fusedValueSpan  []byte

	// valSeen validates the keys declared inside a single container value,
	// which no later expression can reach: keeping them out of d.seen means
	// the main tracker only ever holds reachable keys. Reset (cheaply) for
	// every container value.
	valSeen tracker.SeenTracker
}

// fusedKV is a deferred key-value of an inline table being decoded natively:
// the parts d.fusedParts[lo:hi] of its key, and its decoded value.
type fusedKV struct {
	v      interface{}
	lo, hi int32

<<END_SOURCE>>
